item.command:
"<USER_HOME>\\.cache\\codex-runtimes\\codex-primary-runtime\\dependencies\\native\\powershell\\pwsh.exe" -NoProfile -Command '
$base = '"'D:\\tx-harness-participants\\coverage-attempt01\\pilot-codex-T02-r1'
"'$inputDir = $base + '"'\\inputs'
"'$outDir = $base + '"'\\outputs'
[System.IO.Directory]::CreateDirectory("'$outDir) | Out-Null
$claims = @([System.IO.File]::ReadAllText($inputDir + '"'\\claims.csv') | ConvertFrom-Csv)
"'$versions = [ordered]@{}
$exceptionClaims = @()
$decisions = @(foreach ($c in $claims) {
    $v = if ($c.submitted_date -lt '"'2026-09-01') { 'finance_v2' } else { 'finance_v3' }
    "'$versions[$c.claim_id] = $v
    $prefix = if ($v -eq '"'finance_v2') { 'FIN2' } else { 'FIN3' }
    "'$amount = [long]$c.amount_cents
    $decision = '"'approved'
    "'$reason = '"'FULL'
    "'$approved = 0L
    if ($c.receipt_state -eq '"'missing') {
        "'$decision = '"'rejected'
        "'$reason = '"'NO_RECEIPT'
        "'$rule = if ($prefix -eq '"'FIN2') { 'FIN2-02' } else { 'FIN3-04' }
    } elseif ("'$c.category -eq '"'lodging' -and [int]"'$c.nights -notin 1,2,3) {
        $decision = '"'rejected'
        "'$reason = '"'INVALID_NIGHTS'
        "'$rule = if ($prefix -eq '"'FIN2') { 'FIN2-01' } else { 'FIN3-03' }
    } else {
        if ("'$v -eq '"'finance_v3' -and "'$c.employee_group -eq '"'field' -and "'$c.category -eq '"'taxi') {
            "'$cap = 25000L
            $rule = '"'EXC-01'
            "'$exceptionClaims += $c.claim_id
        } elseif ($v -eq '"'finance_v2') {
            "'$rule = '"'FIN2-01'
            "'$cap = switch ($c.category) { meal {5000L}; taxi {15000L}; lodging {40000L * [int]$c.nights} }
        } else {
            switch ($c.category) {
                meal { $cap = 7500L; $rule = '"'FIN3-01' }
                taxi { "'$cap = 20000L; $rule = '"'FIN3-02' }
                lodging { "'$cap = 60000L * [int]$c.nights; $rule = '"'FIN3-03' }
            }
        }
        "'$approved = [Math]::Min($amount, $cap)
        if ($approved -lt $amount) { $reason = '"'CAP' }
    }
    [pscustomobject][ordered]@{claim_id="'$c.claim_id; decision=$decision; approved_cents=$approved; reason_code=$reason; rule_ids=$rule}
})
$claimed = [long](($claims | Measure-Object amount_cents -Sum).Sum)
$approvedTotal = [long](($decisions | Measure-Object approved_cents -Sum).Sum)
$summary = [ordered]@{claimed_cents=$claimed; approved_cents=$approvedTotal; reduction_cents=($claimed-$approvedTotal); approved_count=@($decisions | Where-Object decision -eq approved).Count; rejected_count=@($decisions | Where-Object decision -eq rejected).Count}
$sourceRules = @{}
foreach ($path in [System.IO.Directory]::GetFiles($inputDir, '"'*.md')) {
    "'$body = [System.IO.File]::ReadAllText($path)
    foreach ($match in [regex]::Matches($body, '"'(?m)"'^## ([A-Z0-9-]+)'"\\r?\\n\\r?\\n(["'^'"\\r\\n]+)')) {
        "'$sourceRules[$match.Groups[1].Value] = [ordered]@{rule_id=$match.Groups[1].Value; path=[System.IO.Path]::GetFileName($path); quote=$match.Groups[2].Value}
    }
}
$used = @($decisions.rule_ids | Sort-Object -Unique)
$evidence = [ordered]@{rules=@(foreach ($id in $used) { if (-not $sourceRules.ContainsKey($id)) { throw "Missing rule $id" }; $sourceRules[$id] })}
$conflicts = [ordered]@{lower_authority_rule_ids=@('"'FAQ-01','OPS-01'); scoped_override=[ordered]@{winner='EXC-01'; overridden_rule='FIN3-02'; claim_ids=@("'$exceptionClaims)}; version_selection=$versions}
$utf8 = [System.Text.UTF8Encoding]::new($false)
[System.IO.File]::WriteAllLines($outDir + '"'\\decisions.csv', @("'$decisions | ConvertTo-Csv -NoTypeInformation), $utf8)
[System.IO.File]::WriteAllText($outDir + '"'\\summary.json', ("'$summary | ConvertTo-Json -Depth 10), $utf8)
[System.IO.File]::WriteAllText($outDir + '"'\\evidence_index.json', ("'$evidence | ConvertTo-Json -Depth 10), $utf8)
[System.IO.File]::WriteAllText($outDir + '"'\\conflicts.json', ("'$conflicts | ConvertTo-Json -Depth 10), $utf8)
$readBack = @([System.IO.File]::ReadAllText($outDir + '"'\\decisions.csv') | ConvertFrom-Csv)
if ("'$readBack.Count -ne $claims.Count -or @($readBack.claim_id | Sort-Object -Unique).Count -ne $claims.Count) { throw '"'Primary key validation failed' }
foreach ("'$r in $evidence.rules) {
    if (-not [System.IO.File]::ReadAllText($inputDir + '"'\\' + "'$r.path).Contains($r.quote)) { throw '"'Quote validation failed' }
}
if ("'$summary.approved_count + $summary.rejected_count -ne $claims.Count -or $approvedTotal -ne 276500 -or $claimed -ne 374900) { throw '"'Totals validation failed' }
"'$decisions | Format-Table
$summary | ConvertTo-Json
'"'Validation passed: unique decisions, totals, and verbatim rule quotes.'
"

"<USER_HOME>\\.cache\\codex-runtimes\\codex-primary-runtime\\dependencies\\native\\powershell\\pwsh.exe" -NoProfile -Command '
$base = '"'D:/tx-harness-participants/coverage-attempt01/pilot-codex-T02-r1'
"'$idir = "$base/inputs"
$odir = "$base/outputs"
[System.IO.Directory]::CreateDirectory($odir) | Out-Null
$csv = @'"'
claim_id,decision,approved_cents,reason_code,rule_ids
Q001,approved,5000,CAP,FIN2-01
Q002,approved,7500,CAP,FIN3-01
Q003,approved,24000,FULL,EXC-01
Q004,approved,20000,CAP,FIN3-02
Q005,rejected,0,NO_RECEIPT,FIN3-04
Q006,approved,120000,CAP,FIN3-03
Q007,rejected,0,INVALID_NIGHTS,FIN3-03
'@
"'$d = @($csv | ConvertFrom-Csv)
$c = @([IO.File]::ReadAllText("$idir/claims.csv") | ConvertFrom-Csv)
$sum = [ordered]@{claimed_cents=[long](($c | Measure-Object amount_cents -Sum).Sum); approved_cents=[long](($d | Measure-Object approved_cents -Sum).Sum); reduction_cents=0; approved_count=@($d | Where-Object decision -eq approved).Count; rejected_count=@($d | Where-Object decision -eq rejected).Count}
$sum.reduction_cents = $sum.claimed_cents - $sum.approved_cents
$rules = @{}
foreach ($file in [IO.Directory]::GetFiles($idir,'"'*.md')) {
    "'$id = $null
    foreach ($line in [IO.File]::ReadAllLines($file)) {
        if ($line.StartsWith('"'## ')) { "'$id = $line.Substring(3).Trim() }
        elseif ($id -and $line.Trim().Length -gt 0) {
            $rules[$id] = [ordered]@{rule_id=$id; path=[IO.Path]::GetFileName($file); quote=$line}
            $id = $null
        }
    }
}
$evidence = [ordered]@{rules=@(foreach ($id in @($d.rule_ids | Sort-Object -Unique)) { if (-not $rules.ContainsKey($id)) { throw "Missing rule $id" }; $rules[$id] })}
$v = [ordered]@{}
foreach ($claim in $c) { $v[$claim.claim_id] = if ($claim.submitted_date -lt '"'2026-09-01') {'finance_v2'} else {'finance_v3'} }
"'$conf = [ordered]@{lower_authority_rule_ids=@('"'FAQ-01','OPS-01'); scoped_override=[ordered]@{winner='EXC-01'; overridden_rule='FIN3-02'; claim_ids=@('Q003')}; version_selection="'$v}
$enc = [Text.UTF8Encoding]::new($false)
[IO.File]::WriteAllText("$odir/decisions.csv",$csv + [Environment]::NewLine,$enc)
[IO.File]::WriteAllText("$odir/summary.json",($sum | ConvertTo-Json),$enc)
[IO.File]::WriteAllText("$odir/evidence_index.json",($evidence | ConvertTo-Json -Depth 10),$enc)
[IO.File]::WriteAllText("$odir/conflicts.json",($conf | ConvertTo-Json -Depth 10),$enc)
$rd = @([IO.File]::ReadAllText("$odir/decisions.csv") | ConvertFrom-Csv)
if ($rd.Count -ne $c.Count -or @($rd.claim_id | Sort-Object -Unique).Count -ne $c.Count) { throw '"'Duplicate or missing decision' }
if (@(Compare-Object ("'$c.claim_id | Sort-Object) ($rd.claim_id | Sort-Object)).Count) { throw '"'Claim set mismatch' }
foreach ("'$r in $evidence.rules) { if (-not [IO.File]::ReadAllText("$idir/$($r.path)").Contains($r.quote)) { throw '"'Quote mismatch' } }
if ("'$sum.claimed_cents -ne 374900 -or $sum.approved_cents -ne 276500 -or $sum.reduction_cents -ne 98400 -or $sum.approved_count -ne 5 -or $sum.rejected_count -ne 2) { throw '"'Summary mismatch' }
"'$sum | ConvertTo-Json
'"'Validated all four output files.'
"

